#pragma once

#include "gfx/image.hpp"
#include "gfx/renderer.hpp"

namespace karafin::screens {

// The "karafin" brand mark ("kara" + accent "fin" with the jellyfish on the i), from
// romfs/wordmark.png (generated by tools/make_brand.py). Sized like Karastream's Wordmark: `height`
// is the height Karastream would draw its wordmark at, so the letters match; the jellyfish rises a
// little above topLeft. Decoded at the drawn size so edges stay crisp.
class Wordmark {
public:
    // ink: dark "kara" + deep accent (romfs/wordmark-ink.png), for white highlights.
    explicit Wordmark(float height, bool ink = false);

    float height() const { return height_; }
    float width() const;
    void draw(gfx::Renderer& r, gfx::Vec2 topLeft);

private:
    float height_;
    gfx::ImagePtr image_;
};

}  // namespace karafin::screens
